func fetchAll(_ urls: [URL]) async throws -> [Data] {
    var out: [Data] = []
    for u in urls { out.append(try await load(u)) }   // suspension point: state saved
    return out
}

// structured concurrency over continuations
await withTaskGroup(of: Data.self) { group in
    for u in urls { group.addTask { try await load(u) } }   // each child is its own state machine
}
